/**
 * What the live site tells us about each post: when it was last modified, and
 * when it was first published.
 *
 * The sitemap is the automatic half. It carries a <lastmod> per URL and is
 * regenerated by the CMS whenever a post changes, so polling it daily keeps
 * "days since update" true without anyone maintaining a spreadsheet column.
 *
 * Published dates are not in the sitemap. They also never change, so they are
 * fetched from the post once and kept — a handful per run, so a first build
 * backfills over a few nights rather than hammering the site in one burst.
 */

const SITEMAP_URL = process.env.BLOG_SITEMAP_URL || "https://www.adsitco.com/post-sitemap.xml";

const FETCH_TIMEOUT_MS = 15000;
const USER_AGENT = "adsitco-report/1.0 (+blog tracker)";

async function fetchText(url, { timeout = FETCH_TIMEOUT_MS } = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeout);
  try {
    const res = await fetch(url, {
      signal: controller.signal,
      headers: { "user-agent": USER_AGENT, accept: "text/html,application/xml;q=0.9,*/*;q=0.8" },
      redirect: "follow",
    });
    if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
    return await res.text();
  } finally {
    clearTimeout(timer);
  }
}

const stripCdata = (s) => s.replace(/^\s*<!\[CDATA\[/, "").replace(/\]\]>\s*$/, "").trim();

function toISODate(value) {
  const text = stripCdata(String(value ?? "")).trim();
  if (!text) return null;
  // Sitemaps use W3C datetime; a plain date is also valid.
  const parsed = Date.parse(text);
  if (!Number.isNaN(parsed)) return new Date(parsed).toISOString().slice(0, 10);
  const iso = /^(\d{4}-\d{2}-\d{2})/.exec(text);
  return iso ? iso[1] : null;
}

/**
 * Every <url> in the post sitemap, as { url, lastmod }.
 *
 * Namespace prefixes vary between sitemap generators, so tags are matched
 * loosely rather than against a fixed prefix. A sitemap index is followed one
 * level down, since some installs split posts across several files.
 */
export async function fetchSitemap(url = SITEMAP_URL, { depth = 0 } = {}) {
  const xml = await fetchText(url);

  // A sitemap index points at further sitemaps rather than listing pages.
  if (/<sitemapindex[\s>]/i.test(xml) && depth < 2) {
    const children = [...xml.matchAll(/<sitemap[\s>][\s\S]*?<\/sitemap>/gi)]
      .map((m) => /<loc[^>]*>([\s\S]*?)<\/loc>/i.exec(m[0])?.[1])
      .filter(Boolean)
      .map(stripCdata);
    const entries = [];
    for (const child of children) {
      try {
        entries.push(...(await fetchSitemap(child, { depth: depth + 1 })));
      } catch {
        // One unreadable child should not lose the rest.
      }
    }
    return entries;
  }

  const entries = [];
  for (const block of xml.matchAll(/<url[\s>][\s\S]*?<\/url>/gi)) {
    const body = block[0];
    const loc = /<loc[^>]*>([\s\S]*?)<\/loc>/i.exec(body)?.[1];
    if (!loc) continue;
    const lastmod = /<lastmod[^>]*>([\s\S]*?)<\/lastmod>/i.exec(body)?.[1];
    entries.push({ url: stripCdata(loc), lastmod: toISODate(lastmod) });
  }
  return entries;
}

/**
 * A post's publication date, from whichever of the usual places carries it.
 * Returns null rather than guessing when none is present.
 */
export function publishedDateFrom(html) {
  const patterns = [
    /<meta[^>]+property=["']article:published_time["'][^>]+content=["']([^"']+)["']/i,
    /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']article:published_time["']/i,
    /"datePublished"\s*:\s*"([^"]+)"/i,
    /<time[^>]+class=["'][^"']*\bpublished\b[^"']*["'][^>]+datetime=["']([^"']+)["']/i,
    /<time[^>]+datetime=["']([^"']+)["'][^>]*class=["'][^"']*\bpublished\b/i,
  ];
  for (const pattern of patterns) {
    const match = pattern.exec(html);
    const iso = match && toISODate(match[1]);
    if (iso) return iso;
  }
  return null;
}

/**
 * Fill in missing published dates, a few at a time.
 *
 * Capped per run because this hits the live site once per post: a first build
 * with a hundred unknowns backfills over a few nights instead of issuing a
 * hundred requests at once, and a published date never needs fetching twice.
 */
export async function backfillPublishedDates(urls, { limit = 25 } = {}) {
  const found = {};
  const failed = [];
  for (const url of urls.slice(0, limit)) {
    try {
      found[url] = publishedDateFrom(await fetchText(url));
    } catch (err) {
      failed.push({ url, error: err.message });
    }
  }
  return { found, failed, remaining: Math.max(0, urls.length - limit) };
}

export { SITEMAP_URL };
